mapper.select:
SELECT COUNT(1) AS LOGIN_CNT
  FROM USER_INFO U
 WHERE U.COMPANY_CODE = #{COMPANY_CODE}
   AND U.USER_ID = #{USERID}
   AND U.PASSWORD = LOWER(#{ENC_PASSWORD})
   AND U.STATUS = 'Y'

mapper.insert:
		
            SELECT LPAD(nextval('log_mgr_seq')::text, 27, '0')
        
        insert into log_mgr_mst (
			     log_seq
			   , user_id
			   , ip
			   , log_date
			   , COMPANY_CODE
			) 
			values ( 
			     #{LOG_SEQ}
			   , #{USERID}
			   , #{IP}
			   , NOW()
			   , #{COMPANY_CODE}
			)

mapper.update:
UPDATE COM_USER A
   SET A.UNLOCK_STR = #{LOCK_STR}
 WHERE A.USER_ID = #{S_USER_ID} 
   AND A.USING_YN = 'Y'

UPDATE COM_USER A
   SET A.USER_PW = #{NEW_PWD_CONNFIRM}
       ,UPDATE_DATE = SYSDATE
 WHERE A.USER_ID = #{USER_ID} 
   AND A.COMPANY_CODE = #{COMPANY_CODE}
   AND A.USER_PW = #{CURRENT_PWD}

mapper.select:
	SELECT CASE WHEN A.LOGIN_FAIL_CNT > 4  THEN 'N' ELSE 'Y' END AS LOGIN_ABLE_YN            
	  FROM COM_USER A
	 WHERE A.USER_ID = #{USERID}
